    bodies={b['body_id']:b for b in json.loads((P/'data/message-bodies.json').read_text())['bodies']}
    body=bodies[ID];context=json.loads((P/'data/we-fixed-it-context.json').read_text());creator=json.loads((P/'data/creator-profile.json').read_text());e=html.escape
    title=body['title']+' — 부부의 수리 소동';description=body['message_sentence'];work=body['canonical_url'];og=URL+'assets/og.jpg';person=creator['url']+'#person'
